const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], money=n=>"₡"+Number(n).toLocaleString();

function fillSelect(el,arr){el.innerHTML=arr.map(x=>`<option>${x}</option>`).join("")}
function detailCard(img,title,tag,body,stats,priceLabel="",price=""){
  return `<img src="${img}" alt="${title}"><div class="detail-body"><span class="tag">${tag}</span><h3>${title}</h3><p>${body}</p><div class="stat-grid">${stats.map(([a,b])=>`<div><small>${a}</small><strong>${b}</strong></div>`).join("")}</div>${price?`<div class="buyline"><span>${priceLabel}</span><span class="price">${price}</span></div>`:""}</div>`;
}

// BIOMETRIC SEQUENCE
(()=>{
 const gate=$("#bioGate"), finger=$("#fingerButton"), eye=$("#eyeButton"), fingerStage=$("#fingerStage"), eyeStage=$("#eyeStage"), p=$("#bioProgress"), msg=$("#bioMessage");
 const checks=[$("#c1"),$("#c2"),$("#c3"),$("#c4"),$("#c5")], title=$("#bioTitle");
 function ok(i,text){checks[i].textContent=text;checks[i].className="ok"}
 finger.onclick=()=>{
   if(finger.disabled)return;
   finger.disabled=true;fingerStage.classList.add("scanning");msg.textContent="SCANNING RIDGE PATTERN...";p.style.width="16%";
   setTimeout(()=>{ok(0,"MATCHED");p.style.width="30%";msg.textContent="IDENTITY MATCH CONFIRMED.";},800);
   setTimeout(()=>{ok(1,"STABLE");p.style.width="42%";fingerStage.classList.remove("scanning");fingerStage.classList.remove("active");eyeStage.classList.remove("locked");eye.disabled=false;$("#eyeCaption").textContent="CLICK EYE TO BEGIN RETINAL SCAN";msg.textContent="RETINAL AUTHENTICATION REQUIRED.";},1600);
 };
 eye.onclick=()=>{
   if(eye.disabled)return;
   eye.disabled=true;eyeStage.classList.add("eye-scanning");msg.textContent="CAPTURING RETINAL MAP...";p.style.width="58%";
   setTimeout(()=>{ok(2,"CLEAR");p.style.width="70%";},700);
   setTimeout(()=>{ok(3,"MATCH");p.style.width="84%";msg.textContent="VEIN RESONANCE TRACE ACCEPTED.";},1350);
   setTimeout(()=>{ok(4,"LEVEL 5");p.style.width="100%";eyeStage.classList.remove("eye-scanning");title.innerHTML='ACCESS<br><span>GRANTED</span>';msg.textContent="ENTERING FAR REACH...";gate.classList.add("granted");},2100);
   setTimeout(()=>{gate.classList.add("closed");document.body.classList.remove("entry-locked");},3300);
 };
})();

