$$(".tab").forEach(b=>b.onclick=()=>{$$(".tab").forEach(x=>x.classList.remove("active"));$$(".tool").forEach(x=>x.classList.remove("active"));b.classList.add("active");$("#"+b.dataset.tab).classList.add("active")});

// Character / crew / dice
fillSelect($("#charPeople"),APP.people);fillSelect($("#charBackground"),APP.backgrounds);fillSelect($("#charCareer"),Object.keys(APP.careers));
function specs(){fillSelect($("#charSpec"),APP.careers[$("#charCareer").value])}$("#charCareer").onchange=specs;specs();
fillSelect($("#crewShip"),APP.ships.map(s=>s.name));
$("#saveCharacter").onclick=()=>{const c={name:$("#charName").value||"Unnamed Traveller",people:$("#charPeople").value,bg:$("#charBackground").value,career:$("#charCareer").value,spec:$("#charSpec").value,level:+$("#charLevel").value};localStorage.setItem("fr_char",JSON.stringify(c));$("#charOutput").innerHTML=`<h3>${c.name}</h3><p>Level ${c.level} ${c.people} ${c.career} — ${c.spec}<br>${c.bg} background</p>`};
$("#saveCrew").onclick=()=>{const c={name:$("#crewName").value||"Unnamed Crew",credits:+$("#crewCredits").value,heat:+$("#crewHeat").value,ship:$("#crewShip").value,notes:$("#crewNotes").value};localStorage.setItem("fr_crew",JSON.stringify(c));$("#crewOutput").innerHTML=`<h3>${c.name}</h3><p>${c.ship} • ${money(c.credits)} • Heat ${c.heat}/100</p>`};
$("#rollDice").onclick=()=>{let sides=+$("#dieType").value.slice(1),count=+$("#dieCount").value,mod=+$("#dieMod").value,rolls=Array.from({length:count},()=>1+Math.floor(Math.random()*sides)),total=rolls.reduce((a,b)=>a+b,0)+mod;$("#diceResult").innerHTML=`${total}<div class="sub">${rolls.join(" + ")} ${mod?((mod>0?"+":"")+mod):""}</div>`};

