// Atlas
(()=>{
 const regs=[...new Set(APP.planets.map(p=>p.region))].sort(), blacks=[...new Set(APP.planets.map(p=>p.blackMarket))].sort();
 $("#planetRegion").innerHTML='<option value="">All regions</option>'+regs.map(x=>`<option>${x}</option>`).join("");
 $("#planetBlack").innerHTML='<option value="">All black-market levels</option>'+blacks.map(x=>`<option>${x}</option>`).join("");
 const markers=$("#planetMarkers"), routes=$("#routeLayer"), detail=$("#planetDetail");
 const seen=new Set();APP.planets.forEach((p,i)=>APP.planets.map((q,j)=>({q,j,d:Math.hypot(p.x-q.x,p.y-q.y)})).filter(o=>o.j!==i).sort((a,b)=>a.d-b.d).slice(0,2).forEach(o=>{let key=[i,o.j].sort((a,b)=>a-b).join("-");if(seen.has(key))return;seen.add(key);let l=document.createElementNS("http://www.w3.org/2000/svg","line");l.setAttribute("x1",p.x);l.setAttribute("y1",p.y);l.setAttribute("x2",o.q.x);l.setAttribute("y2",o.q.y);routes.appendChild(l)}));
 function show(p,b){$$(".planet-marker").forEach(x=>x.classList.remove("active"));if(b)b.classList.add("active");detail.innerHTML=detailCard(p.image,p.name,p.region,p.lore,[["WEALTH",p.wealth],["LAW",p.law],["INDUSTRY",p.industry],["CONTROL",p.faction],["BLACK MARKET",p.blackMarket],["REGION",p.region]])+`<div class="detail-body"><h4>Exports</h4><div class="trade-tags">${(p.exports||[]).map(x=>`<span>${x}</span>`).join("")||"<span>Unknown</span>"}</div><h4>Imports</h4><div class="trade-tags">${(p.imports||[]).map(x=>`<span>${x}</span>`).join("")||"<span>Unknown</span>"}</div><h4>Local Rumour</h4><p class="rumour">“${p.rumour}”</p><h4>Adventure Hooks</h4><div class="trade-tags">${(p.hooks||[]).map(x=>`<span>${x}</span>`).join("")}</div></div>`}
 function render(){let q=$("#planetSearch").value.toLowerCase(),r=$("#planetRegion").value,bm=$("#planetBlack").value;markers.innerHTML="";let list=APP.planets.filter(p=>(!q||(p.name+" "+p.region+" "+p.faction+" "+p.industry+" "+p.lore).toLowerCase().includes(q))&&(!r||p.region===r)&&(!bm||p.blackMarket===bm));list.forEach(p=>{let b=document.createElement("button");b.className="planet-marker";b.dataset.name=p.name;b.style.left=p.x+"%";b.style.top=p.y+"%";b.onclick=()=>show(p,b);markers.appendChild(b)});if(list.length)show(list[0],markers.firstChild)}
 [$("#planetSearch"),$("#planetRegion"),$("#planetBlack")].forEach(x=>x.addEventListener(x.tagName==="INPUT"?"input":"change",render));render();
})();

// Generic catalogue
function setupCatalogue(data,ids,kind){
 const search=$(ids.search),f1=$(ids.f1),f2=$(ids.f2),grid=$(ids.grid),detail=$(ids.detail);
 const field1=kind==="ship"?"role":"cat",field2=kind==="ship"?null:"law";
 if(f1){const vals=[...new Set(data.map(x=>x[field1]))].sort();f1.innerHTML=f1.options[0].outerHTML+vals.map(x=>`<option>${x}</option>`).join("")}
 if(f2){const vals=[...new Set(data.map(x=>x[field2]))].sort();f2.innerHTML=f2.options[0].outerHTML+vals.map(x=>`<option>${x}</option>`).join("")}
 function show(x){
   if(kind==="ship")detail.innerHTML=detailCard(x.image,x.name,x.law,x.desc,[["CLASS",x.cls],["ROLE",x.role],["MIN CREW",x.minCrew],["IDEAL CREW",x.idealCrew],["MAX CREW",x.maxCrew],["CARGO",x.cargo],["HULL",x.hull],["SHIELDS",x.shields],["DEFENCE",x.defense],["THRUST",x.thrust],["HANDLING",(x.handling>=0?"+":"")+x.handling],["HARDPOINTS",x.hardpoints],["MODULES",x.modules]],"BASE PRICE",money(x.price));
   else detail.innerHTML=detailCard(x.image,x.name,x.law,x.desc,[["CATEGORY",x.cat],["RARITY",x.rarity],["STAT",x.stat],["LEGALITY",x.law]],"TYPICAL PRICE",money(x.price));
 }
 function render(){const q=search.value.toLowerCase(),v1=f1?f1.value:"",v2=f2?f2.value:"",budget=ids.budget?+$(ids.budget).value||0:0;grid.innerHTML="";let list=data.filter(x=>(!q||(x.name+" "+(x.role||"")+" "+(x.cat||"")+" "+(x.stat||"")).toLowerCase().includes(q))&&(!v1||x[field1]===v1)&&(!v2||x[field2]===v2)&&(!budget||x.price<=budget));list.forEach(x=>{let e=document.createElement("article");e.className="catalogue-card";e.innerHTML=`<img src="${x.image}" alt="${x.name}"><div class="body"><span class="tag">${x.law}</span><h3>${x.name}</h3><div class="sub">${kind==="ship"?x.cls+" • "+x.role:x.cat+" • "+x.rarity}</div><div class="price">${money(x.price)}</div><div class="sub">${kind==="ship"?"Crew "+x.minCrew+"–"+x.maxCrew+" • Cargo "+x.cargo:x.stat}</div></div>`;e.onclick=()=>show(x);grid.appendChild(e)});if(list.length)show(list[0])}
 [search,f1,f2,ids.budget?$(ids.budget):null].filter(Boolean).forEach(x=>x.addEventListener(x.tagName==="INPUT"?"input":"change",render));render()
}
setupCatalogue(APP.ships,{search:"#shipSearch",f1:"#shipRole",f2:null,budget:"#shipBudget",grid:"#shipGrid",detail:"#shipDetail"},"ship");
$("#economyNote").textContent=APP.economyNote;
setupCatalogue(APP.items,{search:"#itemSearch",f1:"#itemCategory",f2:"#itemLaw",grid:"#itemGrid",detail:"#itemDetail"},"item");
setupCatalogue(APP.black,{search:"#blackSearch",f1:"#blackCategory",f2:"#blackLaw",grid:"#blackGrid",detail:"#blackDetail"},"item");

